<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import AccessibilityAuxiliaries from './AccessibilityAuxiliaries.svelte';
 import {VOICEOVER_CATEGORIES,VOICEOVER_LESSONS,voiceOverCapabilities} from './voiceover-state.js';
 import {voiceOverMenus} from './voiceover-menus.js';
 import {createBrowserPreviews} from './audio-midi-preview.js';
 import {voiceOverAnnouncement} from './voiceover-announcement.js';
 import {describeAudioUtilityControls,focusAudioUtilityControl} from './audio-midi-native.js';
 import './voiceover.css';
 let {window,state: voiceOverState,profile,execute,registerView,preferences,input,sound,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state(''),editor=$state(null),browserVoices=$state([]),speakingCaption=$state(''),practiceValue=$state(false);
 let originalState,originalWindow,originalPreferences,originalInput,originalSound,originalProfile,retired=false,previews,facade;
 const w=$derived(voiceOverState.windows.find(s=>s.windowId===window.id));const a=$derived(preferences?.configuration?.accessibility);const cap=$derived(voiceOverCapabilities(profile));const menus=$derived(voiceOverMenus({state: voiceOverState,windowId:window.id}));
 const names={general:'General',verbosity:'Verbosity',speech:'Speech',navigation:'Navigation',web:'Web',sound:'Sound',visuals:'Visuals',commanders:'Commanders',braille:'Braille',activities:'Activities'};
 const current=()=>!retired&&root?.isConnected&&voiceOverState===originalState&&window===originalWindow&&preferences===originalPreferences&&input===originalInput&&sound===originalSound&&profile===originalProfile&&available&&active;
 async function command(suffix,payload={}){if(!current())return;const r=await execute(`voiceover.${suffix}`,{windowId:window.id},payload);if(current())message=r?.status==='applied'?'':r?.error?.message??'Local operation unavailable.';return r;}
 const setting=(key,value)=>command('settings',{[key]:value});
 const practiceControls=()=>[...(w.sheet==='training'?root.querySelector('.vo-sheet'):root).querySelectorAll('[data-vo-practice]')].filter(el=>!el.disabled&&!el.closest('[inert]'));
 function navigate(operation,guard){if(!current()||guard()!==true)return false;const nodes=practiceControls();if(!nodes.length)return false;const index=nodes.indexOf(document.activeElement);if(operation==='activate'){const node=nodes[index];if(!node)return false;node.click();return node.dataset.avControl;}const next=operation==='previous'?(index<=0?nodes.length-1:index-1):(index+1)%nodes.length;nodes[next].focus();return document.activeElement===nodes[next]?nodes[next].dataset.avControl:false;}
 function keyboard(event){if(!current()||!a?.voiceOver&&w.sheet!=='training')return;const modifier=a?.voiceOverModifier==='caps-lock'?event.getModifierState('CapsLock'):event.ctrlKey&&event.altKey;if(!modifier)return;const operation=event.key==='ArrowRight'?'next':event.key==='ArrowLeft'?'previous':event.key===' '?'activate':event.key.toLowerCase()==='a'?'read':null;if(operation){event.preventDefault();command(w.sheet==='training'&&operation!=='previous'?'training':'navigate',w.sheet==='training'&&operation!=='previous'?{operation:'practice',action:operation}:{operation});}}
 onMount(()=>{originalState=voiceOverState;originalWindow=window;originalPreferences=preferences;originalInput=input;originalSound=sound;originalProfile=profile;previews=createBrowserPreviews(root);const updateVoices=()=>browserVoices=previews.voices();updateVoices();globalThis.speechSynthesis?.addEventListener('voiceschanged',updateVoices);
 const read=async(text,settings,guard)=>{const r=await previews.read(text,settings,guard,caption=>{if(current()&&settings.captions)speakingCaption=caption;});if(current())speakingCaption='';return r;};
 facade={
  available:current,voices:previews.voices,
  describe:()=>({windowId:window.id,category:w?.category,controls:describeAudioUtilityControls(root),keyboardSourceId:input.activeSourceId,localVoices:previews.voices()}),
  focus:async(id,guard)=>{await tick();return current()&&guard()===true&&focusAudioUtilityControl(root,id);},
  read,stop:()=>previews.stop(),navigate,
  focusedDescription:()=>({role:document.activeElement?.getAttribute('role')??document.activeElement?.tagName.toLowerCase()??'',hint:'Use the local VoiceOver modifier and Space to activate.'}),
  focusedText:()=>{const el=document.activeElement;if(!root.contains(el))return '';return el.getAttribute('aria-label')??el.textContent?.trim()??'';},
  keyboardEdit:(key,guard)=>{if(!current()||guard()!==true||document.activeElement!==editor)return null;const start=editor.selectionStart,end=editor.selectionEnd,text=editor.value;const next=key.action==='backspace'?(start===end?text.slice(0,Math.max(0,start-1))+text.slice(end):text.slice(0,start)+text.slice(end)):text.slice(0,start)+key.text+text.slice(end);return next.length<=4096?{text:next}:null;},
  practice:async(action,guard)=>{if(w.sheet!=='training'||!current()||guard()!==true)return false;if(action==='read'){if(!practiceControls().includes(document.activeElement))return false;const text=facade.focusedText();if(!text)return false;const output=sound?.outputs.find(d=>d.id===sound.outputDeviceId);const r=await read(voiceOverAnnouncement(text,a,facade.focusedDescription()),{...a,previewVolume:output?.muted?0:(output?.volume??0)/100},guard);return r.status==='applied';}return !!navigate(action==='next'?'next':'activate',guard);}
 };
 registerView?.(window.id,facade);return()=>{retired=true;globalThis.speechSynthesis?.removeEventListener('voiceschanged',updateVoices);previews.dispose();registerView?.(originalWindow.id,null,facade);};});
</script>
<section bind:this={root} class="voiceover-app" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} class:contrast={a?.increaseContrast} aria-label={cap.label} role="region" tabindex="0" onkeydown={keyboard}>
 <header class="vo-title">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom}/>{/if}<strong>{cap.label}</strong><input data-av-control="search" aria-label="Search VoiceOver Utility" placeholder="Search" maxlength="128" value={w?.search??''} oninput={e=>command('search',{text:e.currentTarget.value})}/></header>
 {#if w&&a&&input}
 <nav class="vo-menus" aria-label="Application menus">{#each menus as m}<button onclick={()=>command('sheet',{menu:w.menu===m.id?null:m.id})}>{m.label}</button>{/each}</nav>{#if w.menu}<div class="vo-menu" role="menu">{#each menus.find(m=>m.id===w.menu)?.children??[] as item}<button role="menuitem" onclick={async()=>{const r=await command(item.request.command.slice(10),item.request.payload);if(r?.status==='applied')command('sheet',{menu:null});}}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 <p class="vo-disclosure">{cap.disclosure}</p>
 <div class="vo-body" inert={!available||!active||w.sheet!=='none'}>
 <aside>{#each VOICEOVER_CATEGORIES.filter(id=>!w.search||names[id].toLowerCase().includes(w.search.toLowerCase())) as id}<button data-av-control={`category:${id}`} class:selected={w.category===id} onclick={()=>command('category',{category:id})}><span>{({general:'◉',verbosity:'▤',speech:'♬',navigation:'✥',web:'◎',sound:'◖',visuals:'▣',commanders:'⌘',braille:'⠿',activities:'▦'})[id]}</span>{names[id]}</button>{/each}</aside>
 <main>
 <h2>{names[w.category]}</h2>
 {#if w.category==='general'}<label><input data-av-control="enable" type="checkbox" checked={a.voiceOver} onchange={e=>setting('voiceOver',e.currentTarget.checked)}/>Enable local VoiceOver reading affordances</label><p>The scene controls remain keyboard accessible. This does not start macOS VoiceOver or Windows Narrator.</p><label>VoiceOver modifier <select value={a.voiceOverModifier} onchange={e=>setting('voiceOverModifier',e.currentTarget.value)}><option value="control-option">Control–Option</option><option value="caps-lock">Caps Lock</option></select></label><button data-av-control="training" onclick={()=>command('sheet',{sheet:'training'})}>Open VoiceOver Training…</button>
 {:else if w.category==='verbosity'}<label>Default verbosity <select data-av-control="verbosity" value={a.voiceOverVerbosity} onchange={e=>setting('voiceOverVerbosity',e.currentTarget.value)}>{#each ['low','medium','high'] as v}<option value={v}>{v}</option>{/each}</select></label><label>Punctuation <select value={a.voiceOverPunctuation} onchange={e=>setting('voiceOverPunctuation',e.currentTarget.value)}>{#each ['none','some','all'] as v}<option value={v}>{v}</option>{/each}</select></label><label><input type="checkbox" checked={a.voiceOverHints} onchange={e=>setting('voiceOverHints',e.currentTarget.checked)}/>Speak local usage hints</label><p>Verbosity and punctuation affect the local announcement text; browser voice pronunciation is browser-dependent.</p>
 {:else if w.category==='speech'}<label>Voice <select data-av-control="voice" value={a.voiceOverVoice} onchange={e=>setting('voiceOverVoice',e.currentTarget.value)}><option value="browser-default">Browser-local default</option>{#each browserVoices as voice}<option value={voice.id}>{voice.name} ({voice.language})</option>{/each}</select></label>{#each [['voiceOverRate','Rate'],['voiceOverPitch','Pitch']] as [key,label]}<label>{label}<input data-av-control={key} type="range" min="0" max="100" value={a[key]} oninput={e=>setting(key,Number(e.currentTarget.value))}/><output>{a[key]}%</output></label>{/each}<p>{browserVoices.length?`${browserVoices.length} actual browser-local voice(s) available.`:'No browser-local speech voices currently available. Preview will report unavailable, not fake speech.'}</p>
 {:else if w.category==='navigation'}<p>Navigate actual local practice controls with {a.voiceOverModifier==='caps-lock'?'Caps Lock':'Control–Option'}–Left/Right Arrow; activate with modifier–Space.</p><div class="vo-practice"><button data-vo-practice data-av-control="practice:first">First practice button</button><button data-vo-practice data-av-control="practice:toggle" aria-pressed={practiceValue} onclick={()=>practiceValue=!practiceValue}>Local toggle {practiceValue?'on':'off'}</button><input data-vo-practice data-av-control="practice:field" aria-label="Practice text field" placeholder="Practice typing"/></div><button onclick={()=>command('navigate',{operation:'next'})}>Next Control</button><button onclick={()=>command('navigate',{operation:'previous'})}>Previous Control</button><button onclick={()=>command('navigate',{operation:'activate'})}>Activate Focused Control</button>
 {:else if w.category==='web'}<p>Local reading demonstration with real headings, links and landmarks. No external page inspection.</p><article aria-label="Practice webpage"><h3>Trail Journal</h3><a href="#vo-local-reading" data-vo-practice data-av-control="practice:link">Read the local journal preview</a><p>A quiet morning beside the lake.</p></article>
 {:else if w.category==='sound'}<label><input type="checkbox" checked={a.monoAudio} onchange={e=>setting('monoAudio',e.currentTarget.checked)}/>Local mono audio preference</label><p>Master playback volume is read directly from shared Sound. No parallel VoiceOver master volume.</p><button onclick={()=>command('read',{operation:'read'})}>Test Local Reading</button>
 {:else if w.category==='visuals'}{#each [['voiceOverCursor','Show local reading cursor'],['captions','Show local captions'],['zoom','Zoom local preview'],['increaseContrast','Increase local contrast'],['reduceMotion','Reduce local motion'],['reduceTransparency','Reduce local transparency']] as [key,label]}<label><input type="checkbox" checked={a[key]} onchange={e=>setting(key,e.currentTarget.checked)}/>{label}</label>{/each}<label>Zoom scale <input type="range" min="1" max="5" step="0.25" value={a.zoomScale} oninput={e=>setting('zoomScale',Number(e.currentTarget.value))}/>{a.zoomScale}×</label><label>Caption style <select value={a.captionsStyle} onchange={e=>setting('captionsStyle',e.currentTarget.value)}>{#each ['default','large','classic'] as v}<option value={v}>{v}</option>{/each}</select></label>
 {:else if w.category==='commanders'}<p>Supported local keyboard commands</p><table><tbody><tr><td>Modifier + → / ←</td><td>Move between practice controls</td></tr><tr><td>Modifier + Space</td><td>Activate focused practice control</td></tr><tr><td>Modifier + A</td><td>Read the focused local control</td></tr></tbody></table><label>Modifier <select value={a.voiceOverModifier} onchange={e=>setting('voiceOverModifier',e.currentTarget.value)}><option value="control-option">Control–Option</option><option value="caps-lock">Caps Lock</option></select></label>
 {:else if w.category==='braille'}<p>No physical braille display is attached to this local scene. The browser is not enumerating host accessibility hardware.</p><div class="vo-braille" aria-label="Local Unicode braille alphabet preview">⠁ ⠃ ⠉ ⠙ ⠑ ⠋ ⠛ ⠓ ⠊ ⠚</div><small>Alphabet sample only, not a braille translation engine.</small>
 {:else}<p>Local practice activities</p><button onclick={()=>command('sheet',{sheet:'training'})}>Keyboard navigation training</button><button onclick={()=>command('auxiliary',{keyboard:!w.keyboard,viewer:false})}>Accessibility Keyboard</button><button onclick={()=>command('auxiliary',{viewer:!w.viewer,keyboard:false})}>Keyboard Viewer</button>{/if}
 <section id="vo-local-reading" class="vo-reading" class:cursor={a.voiceOverCursor} aria-label="Reading Preview"><h3>Local Reading Preview</h3><textarea bind:this={editor} data-av-control="readingText" aria-label="Reading Preview text" maxlength="4096" value={w.readingText} style:font-size={`${a.zoom?a.zoomScale*13:13}px`} oninput={e=>command('text',{text:e.currentTarget.value})}></textarea><div><button data-av-control="read" onclick={()=>command('read',{operation:'read'})}>Read Preview</button><button onclick={()=>command('read',{operation:'stop'})}>Stop</button><button onclick={()=>command('auxiliary',{keyboard:!w.keyboard,viewer:false})}>Accessibility Keyboard</button><button onclick={()=>command('auxiliary',{viewer:!w.viewer,keyboard:false})}>Keyboard Viewer</button></div></section>
 <AccessibilityAuxiliaries session={speakingCaption?{...w,caption:speakingCaption}:w} {input} accessibility={a} {command}/>
 </main></div>
 {#if w.sheet!=='none'}<section class="vo-sheet" role="dialog" aria-label={w.sheet==='training'?'VoiceOver Training':'VoiceOver Utility Help'}>{#if w.sheet==='training'}<h2>{VOICEOVER_LESSONS[w.lesson].title}</h2><p>{VOICEOVER_LESSONS[w.lesson].text}</p><p>Lesson {w.lesson+1} of 3 · {w.completed.includes(w.lesson)?'Completed':'Not yet completed'}</p><div class="vo-practice"><button data-vo-practice data-av-control="lesson:first" onclick={()=>practiceValue=!practiceValue}>First practice button {practiceValue?'on':'off'}</button><button data-vo-practice data-av-control="lesson:second">Second practice button</button><input data-vo-practice data-av-control="lesson:field" aria-label="Practice name" placeholder="Your practice name"/></div><button onmousedown={e=>e.preventDefault()} onclick={()=>command('training',{operation:'practice',action:VOICEOVER_LESSONS[w.lesson].goal})}>Practice {VOICEOVER_LESSONS[w.lesson].goal}</button><button disabled={w.lesson===0} onclick={()=>command('training',{operation:'previous'})}>Back</button><button disabled={w.lesson===2} onclick={()=>command('training',{operation:'next'})}>Continue</button><button onclick={()=>command('training',{operation:'restart'})}>Restart</button>{:else}<h2>VoiceOver Utility Help</h2><p>{cap.disclosure}</p><p>All settings use the original shared Accessibility preferences. Keyboard/Viewer use the original input source and only edit the Reading Preview. Zoom and caption effects remain inside this local window. Speech uses an actual browser-local voice; absent, blocked or failed playback is rejected. Braille hardware and host accessibility services are unavailable.</p>{/if}<button onclick={()=>command('sheet',{sheet:'none'})}>Done</button></section>{/if}
 <footer role="status">{message||w.status||'Local accessibility preview · host settings unchanged'}<button onclick={()=>command('sheet',{sheet:'help'})} aria-label="VoiceOver Utility Help">?</button></footer>
 {:else}<p role="alert">Original accessibility preferences, input source or utility session unavailable.</p>{/if}
</section>
